WITH metrics_long AS (SELECT * FROM (SELECT id, status, discount, amount FROM orders) src UNPIVOT (metric_value FOR measure IN (discount, amount))) SELECT measure, CASE WHEN metric_value >= 67 THEN 'PREMIUM' ELSE 'STANDARD' END AS metric_value_tier, SIZE(COLLECT_SET(status)) AS num_status, MAX(metric_value) FILTER (WHERE measure = 'discount') AS discount_max_metric_value, SUM(CASE WHEN measure = 'discount' THEN metric_value ELSE 0 END) AS discount_metric_value, SUM(metric_value) FILTER (WHERE status = 'COMPLETED') AS completed_total_metric_value FROM metrics_long GROUP BY GROUPING SETS ((measure, CASE WHEN metric_value >= 67 THEN 'PREMIUM' ELSE 'STANDARD' END), (measure)) ORDER BY metric_value_tier DESC;
